"""Convert a closed nginx FLV under its POSIX record_lock (not flock)."""
import fcntl
import json
import os
import pathlib
import subprocess
import sys
from fractions import Fraction

source, destination, ffmpeg, ffprobe, fps_limit = sys.argv[1:]
if fps_limit not in ('source', '30', '60'):
    raise ValueError('Invalid recording FPS limit')
output = pathlib.Path(destination)
# No shell interpolation; all media paths are generated by the application.
try:
    with open(source, 'rb') as recording:
        try:
            fcntl.lockf(recording, fcntl.LOCK_SH | fcntl.LOCK_NB)
        except BlockingIOError:
            sys.exit(75)  # Nginx is still recording; retry later.
        stat = os.fstat(recording.fileno())
        if stat.st_size < 14:
            raise ValueError('Empty recording')
        command = [
            ffmpeg, '-nostdin', '-hide_banner', '-loglevel', 'error', '-xerror', '-y',
            '-i', source, '-map', '0:v:0', '-map', '0:a:0?',
            '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '23', '-pix_fmt', 'yuv420p',
            '-vf', 'pad=ceil(iw/2)*2:ceil(ih/2)*2', '-threads', '2',
            '-c:a', 'aac', '-b:a', '160k', '-movflags', '+faststart',
        ]
        if fps_limit != 'source':
            command.extend(['-fpsmax', fps_limit])
        command.append(destination)
        subprocess.run(command, check=True)
        probe = subprocess.run([
            ffprobe, '-v', 'error', '-show_entries',
            'format=duration:stream=codec_type,codec_name,width,height,avg_frame_rate',
            '-of', 'json', destination,
        ], check=True, capture_output=True, text=True)
        info = json.loads(probe.stdout)
        if float(info.get('format', {}).get('duration', 0)) <= 0 or not any(
            s.get('codec_type') == 'video' and s.get('codec_name') == 'h264' for s in info.get('streams', [])
        ):
            raise ValueError('Invalid output')
        after = os.fstat(recording.fileno())
        if stat.st_size != after.st_size or stat.st_mtime_ns != after.st_mtime_ns:
            raise ValueError('Source changed during conversion')
        video = next(s for s in info['streams'] if s.get('codec_type') == 'video')
        audio = next((s for s in info['streams'] if s.get('codec_type') == 'audio'), None)
        rate = video.get('avg_frame_rate', '0/0')
        fps = float(Fraction(rate)) if rate not in ('0/0', 'N/A', '') else 0
        metadata = {
            'rawBytes': stat.st_size,
            'mp4Bytes': output.stat().st_size,
            'durationSeconds': round(float(info['format']['duration']), 2),
            'width': video.get('width'),
            'height': video.get('height'),
            'fps': round(fps, 2) if fps > 0 else None,
            'videoCodec': video['codec_name'],
            'audioCodec': audio.get('codec_name') if audio else None,
            'format': 'MP4',
        }
    print(json.dumps(metadata))
except Exception:
    output.unlink(missing_ok=True)
    print('No se pudo preparar la grabación; el archivo original se conserva.', file=sys.stderr)
    sys.exit(1)
